def calc_total(prices):
    """Return the total of the prices with tax added, rounded to cents."""
    return round(sum(prices) * (1 + TAX_RATE), 2)


def apply_discount(prices, percent):
    """Lower every price by percent and return the total with tax, rounded to cents."""
    factor = 1 - percent / 100
    return calc_total([price * factor for price in prices])

def test_apply_discount(self):
    self.assertEqual(apply_discount([100], 10), 96.3)
    self.assertEqual(apply_discount([50, 50], 10), 96.3)
    self.assertEqual(apply_discount([100], 0), 107.0)

